@Component("paymentMethod-handler")
@ProcessingGroup("paymentMethod-processing-group")
public class PaymentMethodEventHandler {
	
	// core constructor
	PaymentMethodEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePaymentMethodEvent
     */
    @EventHandler
    public void handle( CreatePaymentMethodEvent event) {
        entityManager.persist(new PaymentMethod(event.getPaymentMethodId(), event.getLast4(), event.getCardholderName(), event.getBillingAddress(), event.getBillingProfile(), event.getMethodType()));
    }

    /*
     * @param	event UpdatePaymentMethodEvent
     */
    @EventHandler
    public PaymentMethod handle( UpdatePaymentMethodEvent event) {
    	entityManager.merge(new PaymentMethod(event.getPaymentMethodId(), event.getLast4(), event.getCardholderName(), event.getBillingAddress(), event.getBillingProfile(), event.getMethodType()));
    }
    
    /*
     * @param	event DeletePaymentMethodEvent
     */
    @EventHandler
    public void on( DeletePaymentMethodEvent event) {
    	PaymentMethod entity = new PaymentMethod();
   
    	// ------------------------------------------
    	// apply the PaymentMethodId
    	// ------------------------------------------
    	entity.setPaymentMethodId( event.getPaymentMethodId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PaymentMethodRepository paymentMethodEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PaymentMethodEventHandler.class.getName());

}
